import { api } from '@/lib/api-client'
import type { OperationalSummary, SummaryKind } from '../lib/summary'

/** The server stamps "generated by" from the signed-in session, so the name argument is ignored. */
export const fetchSummary = (kind: SummaryKind, anchor: string, _generatedBy: string): Promise<OperationalSummary> =>
  api.get<OperationalSummary>(`/report-summary?kind=${kind}&date=${encodeURIComponent(anchor)}`)
